pdfmetrics.registerFont(TTFont('DV-B','/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf'))
INK=HexColor('#153548');TEAL=HexColor('#12848a');MUTED=HexColor('#647883');PALE=HexColor('#e8f3f2');PAGE_W=501
ST={
 'title':ParagraphStyle('Title',fontName='DV-B',fontSize=20.6,leading=28.5,textColor=INK,spaceAfter=15),
 'subtitle':ParagraphStyle('Subtitle',fontName='DV',fontSize=11,leading=17,textColor=MUTED,spaceAfter=15),
 'h1':ParagraphStyle('Heading',fontName='DV-B',fontSize=14.6,leading=19,textColor=INK,spaceBefore=5,spaceAfter=10),
 'h2':ParagraphStyle('Heading2',fontName='DV-B',fontSize=10.4,leading=14,textColor=TEAL,spaceBefore=8,spaceAfter=6),
 'body':ParagraphStyle('Body',fontName='DV',fontSize=8.7,leading=13.5,textColor=INK,spaceAfter=9),
 'small':ParagraphStyle('Small',fontName='DV',fontSize=7.5,leading=11.3,textColor=MUTED,spaceAfter=9),
 'cap':ParagraphStyle('Caption',fontName='DV',fontSize=7.8,leading=11.6,textColor=MUTED,spaceBefore=4,spaceAfter=12),
 'eq':ParagraphStyle('Equation',fontName='DV',fontSize=9.3,leading=14.6,textColor=INK,leftIndent=12,spaceAfter=8,spaceBefore=5),
 'cell':ParagraphStyle('Cell',fontName='DV',fontSize=7.5,leading=10.8,textColor=INK),
}
def P(text,style='body'):return Paragraph(text,ST[style])
def h(text):return P(text,'h1')
def sub(text):return P(text,'h2')
def eq(text):return P(escape(text),'eq')
def page():return PageBreak()
def pic(filename,maxw=480,maxh=280):
 im=PIL.open(F/filename);w,hh=im.size;scale=min(maxw/w,maxh/hh);return RLImage(str(F/filename),width=w*scale,height=hh*scale)
def table(rows,cols=None):
 t=Table([[P(escape(str(c)),'cell') for c in r] for r in rows],colWidths=cols or [PAGE_W/len(rows[0])]*len(rows[0]),repeatRows=1,hAlign='LEFT')
 t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),PALE),('TEXTCOLOR',(0,0),(-1,0),INK),('VALIGN',(0,0),(-1,-1),'TOP'),('LINEBELOW',(0,0),(-1,0),.8,TEAL),('LINEBELOW',(0,1),(-1,-1),.22,HexColor('#dbe9ec')),('TOPPADDING',(0,0),(-1,-1),7),('BOTTOMPADDING',(0,0),(-1,-1),7)]))
 return t
story=[]
# COVER
story += [Spacer(1,29),P('WP 13  |  DISTRICT HEATING SYSTEMS', 'small'),P('Programmable District Heating Thermal Loss and Dispatch Maps with paceval','title'),P('Two versioned pipe-temperature models, hydraulic pressure proxies and a reproducible two-consumer network screening workflow','subtitle'),pic('00_district_heating_hero.png',PAGE_W,245),P('Concept illustration; not a computed research result.','small'),HRFlowable(width='100%',color=TEAL,thickness=1),Spacer(1,9),sub('Verified mathematical research outcome'),P('Using the real paceval MCP service, 22 pipe-level mathematical graphs were executed for 49 synthetic edge conditions, and 25 composed network mathematical graphs were executed for 25 dispatch scenarios. The service reported version 4.26 and no per-point errors for these main studies. Independent 90-digit mathematical audits passed for 547 archived output values.'),sub('Scientific scope and limits'),P('The results describe steady-state, illustrative conditions for a radial source, trunk and two branches. Network flows are prescribed, not hydraulically solved. The local C++ implementation has passed syntax inspection, but its original SDK runtime execution and CTest are pending an ABI-compatible shared library.'),P('14 November 2026  |  paceval Mathematical Research Demonstrator','small'),page()]
# INTRO
story += [h('1. Industrial use case and current state of the art'),P('District heating delivers hot water from a central production plant to buildings through insulated underground supply and return pipework. Heat utility engineers need to evaluate how water loses temperature in transit, which of several consumers may receive insufficient supply temperature, and how network pipe losses and pressure requirements change when weather or operating parameters change.'),P('Consider a hypothetical European urban district. One heat plant supplies a shared main pipe, which divides into two branches serving two customer groups. At a given weather condition the operator can examine alternative supply temperatures and estimate useful customer heat, heat lost along the pipes, and the required hydraulic head. These functions can inform planning and monitoring, but safe dispatch decisions still depend on measured demands, calibrated hydraulic network models, transient behavior and plant limitations.'),sub('What established tools do'),P('Network simulation tools such as DHNx and pandapipes model steady thermal and hydraulic relationships with validated, application-dependent assumptions. More elaborate approaches also handle time-dependent thermal transport, system generation units, storage and optimization. The open-source DistrictHeatingSim workflow incorporates GIS, pipe models and heat-generator design. These tools are context and potential integration partners, not software that the current research claims to replace [1,5,6].'),sub('Recent scientific developments'),P('A 2024 systematic review compares network modelling approaches and industrial tools [1]. A 2025 quasi-dynamic study includes travel-time effects and field measurements [2]. Publications in 2026 develop transfer-function thermal transient methods and source-network-load optimization [3,4]. These developments matter because a static pipe equation does not represent delayed temperature fronts, thermal storage or dynamic customer interactions. The present experiment deliberately studies the smaller, well-defined mathematical kernel used within such workflows.'),sub('Research question'),P('Can the original paceval engine evaluate reusable and versioned single-pipe and three-edge network functions, including full end-to-end heat-delivery sums, pressure-dependent pump proxies, mathematical feasibility guards and sensitivities, for independent weather and dispatch scenarios with a reproducible verification trail?'),page()]
# MODEL
story += [h('2. Defined thermohydraulic screening model'),P('The original WP 13 proposes heat delivery, lumped pipe loss, Darcy friction and a supply temperature margin. Here those four kernels are retained and complemented with a distributed-loss model, two consumers, combined energy accounting, prescribed-flow hydraulic path screening, model version comparison and explicit constraints.'),sub('Pipe temperature: two versioned steady-state models'),eq('h = UA / (m cp)        [dimensionless]'),eq('T_out,v1 = T_in - (T_in - T_amb) h / (1 + h/2)'),eq('T_out,v2 = T_amb + (T_in - T_amb) exp(-h)'),P('The first is a midpoint-lumped loss approximation. The second is the constant-property, uniformly distributed-loss solution, as used in documented district-heating simulators [2,5]. Here UA is the total thermal conductance of a pipe section in W/K, m is water mass flow in kg/s, and cp is J/(kg K). Input and output temperatures are in degrees Celsius; differences use kelvin. The v1 domain is restricted to h less than 1 in this study.'),sub('Thermal and hydraulic expressions'),eq('Q_loss = m cp (T_in - T_out)          [W]'),eq('Q_delivered = m cp (T_out - T_return)  [W]'),eq('u = 4 m / (rho pi D^2)              [m/s]'),eq('Delta_p = f (L/D) rho u^2 / 2       [Pa]'),eq('P_pump,proxy = (m_total/rho) [Delta_p_trunk + max(Delta_p_A,Delta_p_B)] / eta'),P('The pump expression is a deliberately simplified conservative path proxy. It presumes fixed friction factors, no minor losses and prescribed branch mass flows. It is not a converged pipe-network hydraulic solution and must not be used to size an actual pump.'),sub('Network conservation and limits'),eq('m_total = m_A + m_B'),eq('Q_source = m_total cp (T_source - T_return)'),eq('Q_total_delivered = Q_A + Q_B'),eq('Q_source = Q_total_delivered + Q_loss,trunk + Q_loss,A + Q_loss,B'),eq('M_T = min(T_A,out, T_B,out) - T_min'),eq('M_Q = Q_total_delivered - Q_required'),eq('Guard = (M_T >= 0) AND (M_Q >= 0) AND (P_pump <= P_limit)'),P('The physical return-side distribution is not simulated. All consumer return temperatures are prescribed equal to 42 °C. Heat balance concerns the explicitly modelled supply-side network and customer thermal extraction. This simplified setup isolates the mathematical graph functions rather than constituting a calibrated district model.'),page()]
# ARCHITECTURE
story += [h('3. End-to-end mathematical execution architecture'),pic('01_network_schematic.png',PAGE_W,234),P('Figure 1. Conceptual architecture only. The source, trunk and two consumer branches show the algebraic topology, not a surveyed network.','cap'),P('The host reads validated mass flows, weather scenarios, pipe coefficients, temperature thresholds, source temperatures and load requirements. It then calls persistent paceval computation handles. The edge formulas calculate outlet temperature, loss, heat delivery, Darcy pressure drop, pump proxy and derivatives. A separate, composed network group computes the entire source-to-consumers chain directly as paceval expressions. The host decides which acceptable dispatch candidate to retain; paceval evaluates the underlying numerical scores and margins.'),sub('Why both model versions are maintained'),P('Model v1 uses a midpoint-lumped thermal approximation. Model v2 uses an exponential distributed-loss relation. The graph identities remain unchanged during replay; both versions are independently callable and their outputs can be compared on identical inputs. Formula versioning is explicit rather than an implicit replacement of one implementation by another.'),sub('Meaning of operational feasibility'),P('Feasible here means only that the mathematical inequalities for the chosen synthetic inputs are satisfied. It is not an engineering guarantee of temperature quality, pumping capability, mass-flow balance or safe operation. Boundary equality is accepted by the graph guard as stated, and the C++ host separately rejects invalid units, singular denominators and nonfinite inputs.'),page()]
# INVENTORY
story += [h('4. Original paceval integration and function coverage'),P('The original SDK header and bridge sources are included in src/ with their original notices intact. The C++ programme creates persistent computation handles and calls paceval_dGetComputationResult, paceval_dGetComputationResultExt and paceval_dGetMultipleComputationsResultsExt. It uses the documented paceval double/string converter functions when reading and writing numeric CSV records. No compatible local shared library is present here, so these local calls are implemented and syntax-checked but not claimed as executed.'),table([
 ['Mathematical function / industrial use','Execution owner','Graph family or rationale'],
 ['Two pipe outlet temperature versions','paceval','edge: outlet_v1 / outlet_v2'],
 ['Pipe loss, heat delivery and velocity','paceval','edge: heat_loss_*, heat_delivery_*, velocity'],
 ['Pressure drop, pump power and margins','paceval','edge: pressure_drop, pipe_pump_power, margins'],
 ['Analytical thermal sensitivities','paceval','edge: sensitivity_outlet_*_v2'],
 ['Source-trunk-branches temperature chain','paceval','network: trunk_out_* and branch*_*'],
 ['Network total delivery, losses and conservation','paceval','network: delivered_total_*, loss_total_*, heat_balance_*'],
 ['Combined dispatch scores and logical guards','paceval','network: guard_*, dispatch_score_v2'],
 ['Scenario selection, validation, CSV state','C++ host','data and state orchestration; no hidden production math'],
 ['High precision reference and invariants','independent Python/C++','verification only; not publication data'],
],[203,89,209]),P('The full machine-readable inventory, with formula strings, units, versions and execution owners, is provided as results/math_execution_inventory.csv. The original bridge APIs are not to be confused with the independent remote MCP Create/Evaluate/Batch service. The live service reported version 4.26 for this research.'),page()]
# EVIDENCE
story += [h('5. Deterministic workload and verified result scope'),P('The selected experimental scale is intentionally interpretable rather than a claim about throughput. The pipe sweep comprises seven ambient-temperature values and seven pipe conductances with fixed mass flow and material properties. The network sweep spans five ambient conditions and five source supply temperatures. Mass flows and heat demands vary deterministically with the weather setting, and two consumer branches are connected downstream of one trunk.'),table([
 ['Executed remote study','Observed and archived evidence'],
 ['Unique productive mathematical graphs','22 edge + 25 composed network = 47'],
 ['Pipe parameter combinations','49, yielding 1,078 successful graph-point evaluations'],
 ['Network dispatch combinations','25, yielding 625 successful graph-point evaluations'],
 ['Separate narrow model-version boundary case','6 successful graph-point evaluations'],
 ['TINC pointwise sub-study','2 interval-enabled graphs, 3 cases each'],
 ['Independent high-precision checks','547 archived value checks passed'],
 ['Returned pointwise TINC inclusions','6 of 6 selected decimal records enclosed references'],
 ['Local C++ and CTest','Syntax checked; full runtime and CTest not executed'],
],[215,286]),sub('Interpreting the 25 network cases'),P('For the stipulated minimum consumer supply temperature of 68 °C, 15 of 25 synthetic network candidates satisfy the heat-delivery, minimum-supply-temperature and pump-proxy constraints, and 10 do not. The five ambient conditions are −8, −3, 2, 7 and 12 °C; the candidate source temperatures are 70, 74, 78, 82 and 86 °C. All 25 cases were evaluated in each thermal model version.'),P('These temperatures, loads, conductances and limits are invented research assumptions, not public measurements or advice for a specific utility. The nine plotted result panels are based on stored service values; where two scenarios have identical prescribed hydraulic conditions, repeated pump values are a model property and not a measurement of operational stability.'),page()]
# plots
story += [h('6. Pipe losses and outlet-temperature maps'),pic('02_pipe_heat_losses.png',PAGE_W,250),P('Figure 2. Recorded paceval v2 pipe losses under varying ambient temperature and thermal conductance.','cap'),pic('03_pipe_outlet_map.png',PAGE_W,260),P('Figure 3. Pipe outlet temperatures from the actually executed 49-point paceval parameter grid.','cap'),page()]
story += [h('7. Thermal model versions and network margins'),pic('04_pipe_model_versions.png',PAGE_W,245),P('Figure 4. Difference between thermal model versions at identical inputs. This is a model-form comparison, not a numerical engine accuracy comparison.','cap'),pic('06_network_temperature_margin.png',PAGE_W,260),P('Figure 5. Minimum consumer-branch supply-temperature margin from the actual v2 network results.','cap'),page()]
story += [h('8. Dispatch feasibility and customer thermal demand'),pic('05_dispatch_feasibility.png',PAGE_W,240),P('Figure 6. Mathematical acceptance of 15 network cases under the stipulated minimum temperature, heat demand and pump-proxy constraints.','cap'),pic('07_delivered_vs_demand.png',PAGE_W,255),P('Figure 7. Delivered customer heat and synthetic demand for three representative weather scenarios.','cap'),page()]
story += [h('9. Heat-loss fraction and hydraulic path proxy'),pic('08_network_loss_fraction.png',PAGE_W,248),P('Figure 8. Ratios of source heat to modelled total thermal pipe losses across synthetic source-temperature choices.','cap'),pic('10_hydraulic_proxy.png',PAGE_W,240),P('Figure 9. Prescribed-flow pump-power proxy. No dynamic flow or pressure controller is represented.','cap'),page()]
story += [h('10. Three-dimensional dispatch parameter surface'),pic('09_dispatch_surface_3d.png',PAGE_W,400),P('Figure 10. Three-dimensional surface joining 25 actually executed paceval temperature margins. The surface geometry between recorded points is only a plotting interpolation.','cap'),P('The plotted supply margin increases with source temperature for fixed weather and hydraulic inputs, while pipe heat loss depends on ambient temperature, transport conductance and mass flow. This result follows from the stipulated static heat model. It cannot establish safe operation during delayed temperature changes or transient disturbances.'),page()]
story += [h('11. Mathematical model version effect and boundary behavior'),pic('11_delivery_version_delta.png',PAGE_W,270),P('Figure 11. Recorded difference between two physical model versions for total delivered heat. Both versions were evaluated by the original paceval service.','cap'),sub('A deliberately narrow threshold discriminates versions'),P('At an extra synthetic boundary case with ambient temperature −3 °C and source temperature 74 °C, the test threshold was set to 67.777 °C. The paceval midpoint-lumped version evaluated a temperature margin of approximately −0.00044016 K and a false guard, while the distributed-loss version evaluated approximately +0.00063632 K and a true guard. This precision-stress threshold is not an engineering temperature policy.'),P('Such a flip can occur because different thermal approximations produce different physical model outputs, even when each is numerically evaluated correctly. Any real decision threshold should include measured uncertainty, model discrepancy, transient effects, calibrated demand and explicit operating policies. This example is not a claim that one model is universally correct.'),page()]
# audit
story += [h('12. Independent verification and interval boundaries'),P('An independent 90-decimal-digit implementation reconstructed physical pipe temperatures, losses, pressure proxies, branch heat delivery, model-version margins and conservation constraints from the immutable synthetic input CSV files. It does not interpret the paceval expression strings as a second execution engine. All 547 selected archived values passed the predeclared consistency rule. Detailed numerical error data remain in results/independent_numerical_audit.json instead of being printed as an engine-accuracy comparison.'),sub('TINC semantics'),P('Two additional, TINC-enabled paceval expressions were executed for pipe outlet temperature and heat loss, for three fixed input states. In all six selected cases the transmitted decimal lower/upper interval endpoints enclosed the independent pointwise high-precision result. The test covers only those particular input points and text-represented interval endpoints. It does not prove that a whole range of unknown network parameters is enclosed, and does not include metrological sensor uncertainty.'),sub('Input safety and library status'),P('The C++ implementation uses the original documented SDK double-to-string and string-to-double interfaces. Because the numerical string parser can evaluate mathematical expressions, CSV inputs are checked against a strict decimal-literal grammar before SDK conversion. Console and CSV output pass through the SDK converter only in the prepared local execution path. The C++ code and the original SDK bridge compile under a C++17 syntax-only check. No claim is made of successful local linking, CTest, runtime converters or a published GitHub render preview.'),sub('Limitations and next experimental validation'),P('The model assumes steady flow, fixed pipe U and friction factors, constant cp and density, prescribed demand and branch flows, no heat losses on return pipes, no minor hydraulic losses, and no thermal propagation delay. Tests should next include transient transport, measured consumer temperatures, calibrated pipe parameters, flow reversals, zero flow, heat source limits, actual network GIS topology and comparison to full thermo-hydraulic solvers.'),page()]
# ref
story += [h('13. Conclusions and scholarly references'),P('The original paceval Mathematical Engine demonstrably evaluated mathematical formulas for pipe heat losses, temperature propagation, pressure proxies, delivered heat, thermal model alternatives and composed dispatch margins. These functions were reused over actual recorded synthetic parameter sets, and the selected results passed an independent numerical audit. The outcome is a meaningful mathematical research demonstrator that can be studied alongside purpose-built heat-network simulation tools. It is not an industrially qualified network controller, plant optimizer, or dynamic model.'),sub('Reproduction paths'),P('For the recorded data, run <font name="DV-B">python validation/high_precision_reference.py</font> and <font name="DV-B">python scripts/make_figures.py</font>. To exercise the local original SDK when its compatible Linux library is available, run <font name="DV-B">bash scripts/build_and_test.sh /absolute/path/libpaceval_linux_sharedLIB.so</font>. A local run writes separate files under results/local_sdk_*.csv and does not overwrite the remote evidence. No shared library is distributed.'),sub('References'),P('[1] Design and simulation of district heating networks: A review of modeling approaches and tools. <i>Energy</i> 305 (2024), 132189. DOI: 10.1016/j.energy.2024.132189.','small'),P('[2] A quasi-dynamic model and comprehensive simulation study of district heating networks considering temperature delay. <i>Energy</i> 318 (2025), 134855. DOI: 10.1016/j.energy.2025.134855.','small'),P('[3] A transfer function method for thermal transient modeling in district heating networks. <i>Energy</i> 351 (2026), 140834. DOI: 10.1016/j.energy.2026.140834.','small'),P('[4] Integrated Source-Network-Load Modeling and Optimization for District Heating Systems: Recent Advances and Future Directions. <i>Energy Research</i> (2026), DOI: 10.1155/er/8877364.','small'),P('[5] DHNx, simulation models and steady-state pipe heat-loss equations, <link href="https://dhnx.readthedocs.io/en/v0.0.4/simulation_models.html" color="#12848a">online documentation</link>.','small'),P('[6] DistrictHeatingSim 2.0.0, thermo-hydraulic simulation and heat-generator modelling, <link href="https://districtheatingsim.readthedocs.io/en/latest/" color="#12848a">online documentation</link>.','small'),P('[7] HeatNetSim, open-source heating/cooling network modelling, <link href="https://doi.org/10.1016/j.energy.2024.133588" color="#12848a">Energy research publication</link>.','small'),P('[8] paceval Mathematical Engine, <link href="https://paceval.com/api/" color="#12848a">original SDK API reference</link> and <link href="https://paceval.com/product-brief/" color="#12848a">product brief</link>.','small'),P('Reference access: 14 November 2026. All new numeric research claims are linked to the supplied paceval MCP execution manifest and observed-result CSVs.','small')]
D=SimpleDocTemplate(str(OUT),pagesize=A4,rightMargin=47,leftMargin=47,topMargin=48,bottomMargin=47,title='District Heating Network Thermal Loss and Dispatch Maps with paceval',author='paceval Mathematical Research',subject='Original remote paceval graph execution and synthetic thermal network research')
def footer(canvas,doc):
 canvas.saveState();w,hh=A4;canvas.setStrokeColor(HexColor('#dbe8eb'));canvas.line(47,43,w-47,43);canvas.setFont('DV',7);canvas.setFillColor(MUTED)
